from pathlib import Path
import re

def verify(workspace_path, external_services_path=None):
    actions_file = Path(workspace_path) / 'actions_summary.txt'
    if not actions_file.exists():
        return {'pass': False, 'score': 0.0, 'feedback': 'actions_summary.txt not found in workspace'}
    content = actions_file.read_text(encoding='utf-8', errors='ignore').lower()
    checks = [
        ('chargeback or safeguard or vsc', bool(re.search(r'chargeback|safeguard|vsc', content))),
        ('funding delay (wells fargo or SL-2026-0412)', bool(re.search(r'wells.?fargo|sl.?2026.?0412|funding', content))),
        ('payoff variance ($290)', bool(re.search(r'290|payoff|variance|trade', content))),
        ('cash discrepancy ($180)', bool(re.search(r'180|cash.{0,20}(discrepancy|short|deposit)|deposit.{0,20}short', content))),
        ('floorplan sold-not-paid', bool(re.search(r'floorplan|floor.?plan|sold.{0,10}paid|snp', content))),
    ]
    failed = [name for name, result in checks if not result]
    passed = [name for name, result in checks if result]
    if failed:
        return {'pass': False, 'score': len(passed)/len(checks), 'feedback': f'actions_summary.txt missing references to: {failed}. Found references to: {passed}'}
    return {'pass': True, 'score': 1.0, 'feedback': f'actions_summary.txt references all five issues: chargeback, funding delay, payoff variance, cash discrepancy, floorplan'}

