from pathlib import Path
import json
import re

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'No external services path provided; cannot check email or Slack'}
    darius = 'darius.kim@sunshineauto.com'
    elena = 'elena.brooks@sunshineauto.com'
    topic_re = re.compile(r'floorplan|floor.?plan|sold.{0,15}paid|snp|8xj472|interest.{0,20}accru|accru.{0,20}interest|28.?700')
    name_res = {
        darius: re.compile(r'darius\.kim|darius\s+kim|\bdarius\b'),
        elena: re.compile(r'elena\.brooks|elena\s+brooks|\belena\b'),
    }
    mailbox_path = Path(external_services_path) / 'mailbox.json'
    slack_path = None
    for candidate_name in ('slack.json', 'slack_data.json'):
        candidate = Path(external_services_path) / candidate_name
        if candidate.exists():
            slack_path = candidate
            break
    if not mailbox_path.exists() and slack_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'Neither mailbox.json nor Slack service state was found'}
    darius_notified = False
    elena_notified = False
    if mailbox_path.exists():
        with open(mailbox_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        sent_emails = [e for e in data.get('emails', []) if e.get('folder', '').lower() == 'sent']
        for email in sent_emails:
            to_addr = (email.get('to_addr', '') or '').lower()
            cc_addr = (email.get('cc_addr', '') or '').lower()
            recipients = to_addr + ' ' + cc_addr
            body = (email.get('body_text', '') or '').lower()
            subject = (email.get('subject', '') or '').lower()
            text = body + ' ' + subject
            if not topic_re.search(text):
                continue
            if darius in recipients:
                darius_notified = True
            if elena in recipients:
                elena_notified = True
    if slack_path is not None:
        with open(slack_path, 'r', encoding='utf-8') as f:
            slack_data = json.load(f)
        raw_workspaces = slack_data.get('workspaces')
        workspaces = raw_workspaces if isinstance(raw_workspaces, dict) else {'default': slack_data}
        for workspace in workspaces.values():
            if not isinstance(workspace, dict):
                continue
            users = workspace.get('users') or {}
            channels = workspace.get('channels') or {}
            bot_ids = {uid for uid, user in users.items() if isinstance(user, dict) and user.get('is_bot')}
            if workspace.get('bot_user_id'):
                bot_ids.add(workspace['bot_user_id'])
            person_ids = {}
            for addr in (darius, elena):
                person_ids[addr] = {
                    uid for uid, user in users.items()
                    if isinstance(user, dict) and ((user.get('profile') or {}).get('email') or '').lower() == addr
                }
            for channel_id, channel_messages in (workspace.get('messages') or {}).items():
                channel = channels.get(channel_id) or {}
                direct_ids = set(channel.get('members') or [])
                if channel.get('is_im') and channel.get('user'):
                    direct_ids.add(channel['user'])
                for message in channel_messages or []:
                    if not isinstance(message, dict) or message.get('user') not in bot_ids:
                        continue
                    text = (message.get('text') or '').lower()
                    if not topic_re.search(text):
                        continue
                    for addr in (darius, elena):
                        named = bool(name_res[addr].search(text))
                        mentioned = any('<@' + uid.lower() + '>' in text for uid in person_ids[addr])
                        direct = bool(person_ids[addr] & direct_ids)
                        if named or mentioned or direct:
                            if addr == darius:
                                darius_notified = True
                            else:
                                elena_notified = True
    missing = []
    if not darius_notified:
        missing.append(darius)
    if not elena_notified:
        missing.append(elena)
    if missing:
        return {'pass': False, 'score': (2 - len(missing)) / 2, 'feedback': f'Floorplan notification missing for recipients: {missing}. darius_notified={darius_notified}, elena_notified={elena_notified}'}
    return {'pass': True, 'score': 1.0, 'feedback': f'Floorplan notification sent to both {darius} and {elena} referencing sold-not-paid/floorplan details'}

