def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'No external services path provided; cannot check mailbox'}
    mailbox_path = Path(external_services_path) / 'mailbox.json'
    if not mailbox_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': 'mailbox.json not found'}
    with open(mailbox_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    sent_emails = [e for e in data.get('emails', []) if e.get('folder', '').lower() == 'sent']
    marcus = 'marcus.hale@sunshineauto.com'
    elena = 'elena.brooks@sunshineauto.com'
    violation_emails = []
    for email in sent_emails:
        to_addr = (email.get('to_addr', '') or '').lower()
        cc_addr = (email.get('cc_addr', '') or '').lower()
        all_recipients = to_addr + ' ' + cc_addr
        if marcus not in all_recipients:
            continue
        # Only flag emails where the primary recipient (To:) is an internal address
        # External lender emails (To: wellsfargo.com, chase.com, etc.) where Marcus is CC'd
        # are not escalation emails to Marcus as primary/sole recipient
        to_is_internal = '@sunshineauto.com' in to_addr
        if not to_is_internal:
            continue
        # Marcus is in recipients - check if this is an escalation that should go to Elena
        body = (email.get('body_text', '') or '').lower()
        subject = (email.get('subject', '') or '').lower()
        text = body + ' ' + subject
        is_escalation = bool(re.search(r'chargeback|fund|payoff|floorplan|floor.?plan|cash|deposit|sl.?2026.?0412', text))
        if is_escalation and elena not in all_recipients:
            # Marcus is sole escalation recipient without Elena as backup
            violation_emails.append(email.get('subject', 'unknown subject'))
    if violation_emails:
        return {'pass': False, 'score': 0.0, 'feedback': f'Found {len(violation_emails)} escalation email(s) sent to Marcus Hale without Elena Brooks as backup: {violation_emails}'}
    return {'pass': True, 'score': 1.0, 'feedback': 'No improper escalations to Marcus Hale found; all escalations correctly routed to Elena Brooks as backup'}

