from pathlib import Path
import json
import re

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {'pass': False, 'score': 0.0, 'feedback': 'No external services path provided; cannot check mailbox'}
    mailbox_path = Path(external_services_path) / 'mailbox.json'
    if not mailbox_path.exists():
        return {'pass': False, 'score': 0.0, 'feedback': 'mailbox.json not found'}
    with open(mailbox_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    sent_emails = [e for e in data.get('emails', []) if e.get('folder', '').lower() == 'sent']
    priya = 'priya.bennett@sunshineauto.com'
    elena = 'elena.brooks@sunshineauto.com'

    # Tier regex: "$51" then a dash (hyphen OR en-dash OR em-dash) then "$500",
    # with optional spaces around the dash.
    tier_pattern = re.compile(r'\$?\s*51\s*[-\u2013\u2014]\s*\$?\s*500')

    best_found = []
    best_missing = ['original $5,000', 'recalculated $4,710', 'tier $51-$500']
    match_found = False

    for email in sent_emails:
        to_addr = (email.get('to_addr', '') or '').lower()
        cc_addr = (email.get('cc_addr', '') or '').lower()
        recipients = to_addr + ' ' + cc_addr
        if priya not in recipients or elena not in recipients:
            continue
        body = (email.get('body_text', '') or '').lower()
        subject = (email.get('subject', '') or '').lower()
        text = body + ' ' + subject
        is_payoff = bool(re.search(r'payoff|trade.{0,20}vari|gross', text))
        if not is_payoff:
            continue
        match_found = True

        has_original = bool(re.search(r'5[,.]?000', text))
        has_recalc = bool(re.search(r'4[,.]?710', text))
        has_tier = bool(tier_pattern.search(text))

        found = []
        missing = []
        if has_original: found.append('original $5,000')
        else: missing.append('original $5,000')
        if has_recalc: found.append('recalculated $4,710')
        else: missing.append('recalculated $4,710')
        if has_tier: found.append('tier $51-$500')
        else: missing.append('tier $51-$500')

        if not missing:
            return {'pass': True, 'score': 1.0, 'feedback': f'Trade payoff escalation includes all required figures and tier: {found}'}
        if len(found) > len(best_found):
            best_found = found
            best_missing = missing

    if match_found:
        return {'pass': False, 'score': len(best_found) / 3.0, 'feedback': f'Trade payoff escalation found: {best_found}, missing: {best_missing}'}
    return {'pass': False, 'score': 0.0, 'feedback': 'No trade payoff escalation email found to both priya.bennett and elena.brooks'}

